# One-off source for content/lessons/22-alevel-english.json (the A level English climb's lessons, England Years 12 and 13).
# Run: python3 tools/alevel_english_lessons_src.py   (then npm run build). Kept so the lessons can be regenerated.
# Content follows the DfE's GCE AS and A level subject content for English literature and English language (2014).
# Questions and texts are PopSpell's own or public domain (exam-english/alevel.js, exam-english/texts.js).
import json, os

ROOT = os.path.join(os.path.dirname(__file__), "..")
HERE = lambda *p: os.path.join(ROOT, *p)
R, W = "Reading: understanding stories", "Writing: creating texts"
COURSE = {"al1": "A level English Literature", "al2": "A level English Language"}

# topic id: (title, strand, intention, criteria, start, teach, check, home, vocab, understand, lookFor)
