COURSE_TOPICS = {"al1": [k for k in T if k.startswith("al1-")], "al2": [k for k in T if k.startswith("al2-")]}
N = {"al1": 1, "al2": 2}
SHORT = {"al1": "Literature", "al2": "Language"}
WRITE = {"al1": ("critical essay", "Critical essay"), "al2": ("original writing with commentary", "Original writing with commentary")}
MINI = {"al1": ["Mini paper: unseen poetry (A level Literature)", "Mini paper: comparison (A level Literature)"],
        "al2": ["Mini paper: textual analysis (A level Language)", "Mini paper: child language (A level Language)"]}
L = lambda s: f"lesson-alevel-english-{s}"
lessons = []
for key in ["al1", "al2"]:
    n, short, course = N[key], SHORT[key], COURSE[key]
    base = {"level": "Senior", "subject": "Literacy", "codes": [], "england": True, "alevel": course}
    lessons.append(dict(base, **{"id": L(f"{key}-start-here"), "strand": R, "title": f"A level English climb, {short}: start here",
        "intention": f"We are finding out which {course} topics are secure and which to learn first, learning what the course expects, and making a plan.",
        "criteria": [f"I can try a question on each {short} topic and show what I already know.", f"I know how {course} is examined and what coursework is worth.", "I have a plan with exam and coursework dates."],
        "steps": {"start": f"Talk about the goal: {course}. Find out the exam board and the set texts{' or topics' if key == 'al2' else ''}: the climb's method works for any board.",
                  "teach": f"Read the \"What the exam expects: {course}\" sheet together. Then do the check (online or on paper), with no help: it's a map, not a test.",
                  "practise": f"The \"A level English climb: {short} check\" sheet, or the online check.",
                  "check": f"Mark the check together. Fill in the \"A level English climb: {short} tracker\" sheet: topics marked ✗ go first. Agree the exam dates, the coursework deadline and sessions a week."},
        "use": [f"{key}-check"], "home": "Read every day: a set text, a long article, or a transcript, and write one sentence on how it works.",
        "vocab": "specification, assessment objective, coursework, mark bands, argument",
        "understand": "Why find out the exam board first?", "lookFor": "Says each board sets its own texts, papers and coursework rules, though the skills are the same."}))
    for i, tid in enumerate(COURSE_TOPICS[key], 1):
        title, strand, intention, criteria, start, teach, check, home, vocab, understand, look = T[tid]
        lessons.append(dict(base, **{"id": L(tid), "strand": strand, "title": f"A level English climb {n}.{i}: {title} ({short})",
            "intention": intention, "criteria": criteria,
            "steps": {"start": start, "teach": teach,
                      "practise": f"The \"A level English practice {n}.{i}: {title}\" sheet (quick questions, then an exam-style question marked with the bands), then the online practice.",
                      "check": check},
            "use": [tid], "home": home, "vocab": vocab, "understand": understand, "lookFor": look}))
    lessons.append(dict(base, **{"id": L(f"{key}-writing"), "strand": W, "title": f"A level English climb, {short}: {WRITE[key][0]}",
        "intention": f"We are learning to plan, draft, check and improve a {WRITE[key][0]}, aiming at grade A or B.",
        "criteria": ["I can plan before drafting.", "I can check my draft against the list and correct it.", "I can act on one round of feedback."],
        "steps": {"start": "What makes the difference between a C and an A in this kind of writing? List three things.",
                  "teach": "Model the plan on the task sheet. Draft in one sitting. Then check against the list, compare with the model on the answers page, and agree one change that would lift it a band.",
                  "practise": f"The \"A level English writing task: {WRITE[key][0]} ({course})\" sheet, or the writing task on the My next step page.",
                  "check": "Mark with the bands on the answers page. Agree one target for the redraft."},
        "use": [], "home": "Write for 20 minutes once a week and check it against the list.",
        "vocab": "plan, draft, redraft, band, style model" if key == "al2" else "thesis, plan, draft, redraft, band",
        "understand": "Why aim to change one thing in a redraft, not ten?", "lookFor": "Says one clear target is achievable and lifts the work a band; ten at once gets nothing done well."}))
    lessons.append(dict(base, **{"id": L(f"{key}-mini-papers"), "strand": R, "title": f"A level English climb, {short}: mini papers",
        "intention": "We are practising under exam conditions: timed answers marked with the bands, then using the marks to plan.",
        "criteria": ["I can plan and write a sustained answer in the time.", "I can mark my answer honestly with the bands.", "I know which topics to go back to."],
        "steps": {"start": "Look at the mini paper's times. How long will you spend reading and planning?",
                  "teach": "Sit a mini paper, timed. Then mark it with the answers page and the bands, and note on the tracker what to work on.",
                  "practise": f"The stage's mini paper sheets (\"{MINI[key][0]}\" and \"{MINI[key][1]}\"), or the mini paper on the My next step page.",
                  "check": "About 60% or more means the stage is going well. Otherwise, go back to the topics that lost marks."},
        "use": [f"{key}-mixed"], "home": "Rewrite the weakest paragraph of the mini paper answer.",
        "vocab": "timing, bands, argument, sustained",
        "understand": "Why spend ten minutes planning a one-hour answer?", "lookFor": "Says the argument decides what to analyse; without a plan the answer becomes a list."}))

common = {"level": "Senior", "subject": "Literacy", "strand": R, "codes": [], "england": True, "alevel": "A level English (Years 12 and 13)"}
lessons.append(dict(common, **{"id": L("my-next-step"), "title": "A level English climb: my next step (working on your own, Years 12 and 13)",
    "intention": "We are learning to work through the A level English climb on our own: one step a session, marking our own answers honestly.",
    "criteria": ["I can find my next step on the climb page and do it.", "I can mark a written answer with the bands.", "I know when to move on."],
    "steps": {"start": "Open popspell.com/english-climb.html?course=alevel together and press My next step.",
              "teach": "Show how the page works: the check, topics in order, a writing task with a checklist, then a mini paper. Show how to mark an answer with the bands: find the best fit, then go up or down.",
              "practise": "The \"A level English climb: my route through Years 12 and 13\" sheet to keep, then the first step on the page.",
              "check": "Ask them to explain what secure means and what they'll do next session."},
    "use": ["al1-check", "al2-check"], "home": "Read every day, and do a climb session three or four times a week.",
    "vocab": "self-assessment, bands, model answer, secure",
    "understand": "Why mark your own answer with the bands, not just read the model?",
    "lookFor": "Says the bands show exactly what is missing for the next level, so you know what to change."}))

out = {"section": "England: A level English exam climb (Literature and Language, Years 12 and 13)", "lessons": lessons}
with open(HERE("content", "lessons", "22-alevel-english.json"), "w") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print(len(lessons), "lessons")
